import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.ChIlRNAd.js";const m=JSON.parse('{"title":"Premiers pas","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/first-steps.md","filePath":"fr/guide/first-steps.md"}'),r={name:"fr/guide/first-steps.md"};function o(n,e,l,u,c,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="premiers-pas" tabindex="-1">Premiers pas <a class="header-anchor" href="#premiers-pas" aria-label="Permalink to &quot;Premiers pas&quot;">​</a></h1><p>Ce guide vous accompagne dans vos premières minutes avec Nid.</p><hr><h2 id="creer-votre-compte" tabindex="-1">Créer votre compte <a class="header-anchor" href="#creer-votre-compte" aria-label="Permalink to &quot;Créer votre compte&quot;">​</a></h2><p>Ouvrez l&#39;application dans votre navigateur (par défaut : <a href="http://localhost:3000" target="_blank" rel="noreferrer">http://localhost:3000</a>). L&#39;écran de connexion a deux onglets : <strong>Connexion</strong> et <strong>Créer un compte</strong>.</p><h3 id="compte-local" tabindex="-1">Compte local <a class="header-anchor" href="#compte-local" aria-label="Permalink to &quot;Compte local&quot;">​</a></h3><ol><li>Ouvrez l&#39;onglet <strong>Créer un compte</strong></li><li>Saisissez votre email et un mot de passe (8 caractères minimum)</li><li>Validez avec <strong>Créer un compte</strong></li></ol><h3 id="connexion-via-un-fournisseur" tabindex="-1">Connexion via un fournisseur <a class="header-anchor" href="#connexion-via-un-fournisseur" aria-label="Permalink to &quot;Connexion via un fournisseur&quot;">​</a></h3><p>Si l&#39;administrateur les a configurés, des boutons <strong>Se connecter avec Google</strong> (ou Microsoft, Discord, Facebook, LinkedIn, <strong>Se connecter via SSO</strong>) apparaissent sous le formulaire. Votre nom et votre avatar sont récupérés automatiquement.</p><div class="tip custom-block"><p class="custom-block-title">Fusion de comptes</p><p>Si vous créez d&#39;abord un compte local puis vous connectez avec Google en utilisant le même email, les deux comptes sont automatiquement fusionnés.</p></div><p>Si la <a href="./settings.html#securite">2FA</a> est activée, un écran <strong>Vérification en deux étapes</strong> demande ensuite le code à 6 chiffres de votre application d&#39;authentification.</p><hr><h2 id="devenir-administrateur" tabindex="-1">Devenir administrateur <a class="header-anchor" href="#devenir-administrateur" aria-label="Permalink to &quot;Devenir administrateur&quot;">​</a></h2><p>Le premier utilisateur doit être promu administrateur. Trois options :</p><h3 id="option-a-—-automatiquement-recommande" tabindex="-1">Option A — Automatiquement (recommandé) <a class="header-anchor" href="#option-a-—-automatiquement-recommande" aria-label="Permalink to &quot;Option A — Automatiquement (recommandé)&quot;">​</a></h3><p>Avant de créer votre compte, ajoutez dans le fichier <code>.env</code> :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ADMIN_EMAIL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">votre@email.com</span></span></code></pre></div><p>L&#39;utilisateur qui s&#39;inscrit avec cet email obtient automatiquement le rôle admin.</p><h3 id="option-b-—-en-base-de-donnees" tabindex="-1">Option B — En base de données <a class="header-anchor" href="#option-b-—-en-base-de-donnees" aria-label="Permalink to &quot;Option B — En base de données&quot;">​</a></h3><p>Si votre compte existe déjà :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> psql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -U</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gmailmanager</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gmailmanager</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;UPDATE users SET role = &#39;admin&#39; WHERE email = &#39;votre@email.com&#39;;&quot;</span></span></code></pre></div><p>Déconnectez-vous puis reconnectez-vous pour que le nouveau rôle prenne effet.</p><h3 id="option-c-—-via-l-interface" tabindex="-1">Option C — Via l&#39;interface <a class="header-anchor" href="#option-c-—-via-l-interface" aria-label="Permalink to &quot;Option C — Via l&#39;interface&quot;">​</a></h3><p>Un administrateur existant peut changer le <strong>Rôle</strong> d&#39;un utilisateur depuis <a href="./admin.html#utilisateurs">Admin › Utilisateurs</a>.</p><hr><h2 id="connecter-un-compte-gmail" tabindex="-1">Connecter un compte Gmail <a class="header-anchor" href="#connecter-un-compte-gmail" aria-label="Permalink to &quot;Connecter un compte Gmail&quot;">​</a></h2><p>Tant qu&#39;aucun compte Gmail n&#39;est connecté, la Vue d&#39;ensemble affiche « Aucun compte Gmail connecté » avec le lien <strong>Connecter un compte Gmail</strong>.</p><ol><li>Allez dans <strong>Paramètres › Comptes Gmail</strong> (sur mobile : <strong>Plus › Comptes Gmail</strong>)</li><li>Cliquez sur <strong>Ajouter un compte Gmail</strong></li><li>Autorisez l&#39;accès dans la fenêtre Google (accès demandés : <code>gmail.modify</code>, <code>gmail.labels</code>)</li><li>De retour dans Nid, un message confirme « Compte Gmail connecté : … »</li></ol><div class="warning custom-block"><p class="custom-block-title">Écran d&#39;avertissement Google</p><p>Si votre projet Google Cloud est en mode &quot;Test&quot;, un écran d&#39;avertissement apparaîtra. Cliquez sur <strong>Paramètres avancés</strong> → <strong>Accéder à nid (non sécurisé)</strong>. C&#39;est normal pour un usage personnel self-hosted.</p></div><p>Répétez l&#39;opération pour d&#39;autres comptes, dans la limite fixée par l&#39;administrateur (affichée « N / max comptes »). Le compte actif se choisit dans le sélecteur <strong>Compte Gmail</strong> de la barre latérale (sur mobile : menu de l&#39;avatar). Toutes les pages affichent les données de ce compte.</p><hr><h2 id="votre-premier-nettoyage" tabindex="-1">Votre premier nettoyage <a class="header-anchor" href="#votre-premier-nettoyage" aria-label="Permalink to &quot;Votre premier nettoyage&quot;">​</a></h2><ol><li>Ouvrez <strong>Nettoyage</strong> et cliquez sur <strong>Analyser la boîte</strong> : Nid regroupe par expéditeur vos newsletters et mails de listes de diffusion (l&#39;analyse tourne en arrière-plan, vous pouvez quitter la page).</li><li>Triez par <strong>Taille</strong> ou <strong>Jamais ouverts</strong>.</li><li>Sur un expéditeur, cliquez sur <strong>Tout supprimer</strong> : ses mails partent vers la corbeille Gmail.</li><li>Un toast « Suppression de N mails dans 10 s » apparaît avec <strong>Annuler</strong> : vous avez 10 secondes pour changer d&#39;avis.</li></ol><p>Le détail est dans <a href="./cleanup.html">Nettoyage</a>. Pour agir sur n&#39;importe quelle recherche Gmail, voir <a href="./mails.html">Mails</a>.</p><div class="tip custom-block"><p class="custom-block-title">Corbeille Gmail</p><p>« Supprimer » envoie les mails dans la <strong>corbeille Gmail</strong>, où Gmail les garde 30 jours avant de les effacer.</p></div><hr><h2 id="votre-premiere-sauvegarde-sur-le-nas" tabindex="-1">Votre première sauvegarde sur le NAS <a class="header-anchor" href="#votre-premiere-sauvegarde-sur-le-nas" aria-label="Permalink to &quot;Votre première sauvegarde sur le NAS&quot;">​</a></h2><ol><li>Dans <strong>Mails</strong>, faites une recherche (ex. : <code>older_than:1y</code>)</li><li>Cliquez sur <strong>Tout sauvegarder sur le NAS</strong> (ou sélectionnez des mails puis <strong>Sauvegarder sur le NAS</strong>)</li><li>La progression s&#39;affiche sur la page et dans <a href="./activity.html">Activité</a></li></ol><p>Les mails sauvegardés se retrouvent dans <a href="./archives.html">Archives</a>, avec une recherche plein texte. Pour une sauvegarde régulière, activez la <strong>Sauvegarde automatique</strong> du compte dans <a href="./settings.html#comptes-gmail">Paramètres › Comptes Gmail</a>.</p><hr><h2 id="et-ensuite" tabindex="-1">Et ensuite ? <a class="header-anchor" href="#et-ensuite" aria-label="Permalink to &quot;Et ensuite ?&quot;">​</a></h2><ul><li><a href="./rules.html"><strong>Règles &amp; libellés</strong></a> — automatisez le tri et le nettoyage</li><li><a href="./overview.html"><strong>Vue d&#39;ensemble</strong></a> — l&#39;état de votre compte et les suggestions</li><li><a href="./settings.html"><strong>Paramètres</strong></a> — 2FA, notifications, import/export</li></ul>`,42)])])}const h=a(r,[["render",o]]);export{m as __pageData,h as default};
